// Process quest generation request
const questData = $input.first().json;
const { 
  action, // 'generate', 'update', 'complete', 'branch', 'discover', 'abandon'
  campaignId,
  questType, // 'main', 'side', 'personal', 'faction', 'discovery', 'emergency'
  generationMethod, // 'procedural', 'ai', 'template', 'contextual', 'consequence'
  triggerContext = {},
  partyData = {},
  worldContext = {},
  difficultyPreference, // 'easy', 'normal', 'hard', 'adaptive'
  questParameters = {}
} = questData;

// Validate required fields
if (!action || !campaignId) {
  throw new Error('Missing required fields: action, campaignId');
}

// Prepare quest generation context
const questContext = {
  action,
  campaignId,
  questType: questType || 'side',
  generationMethod: generationMethod || 'contextual',
  triggerContext,
  partyData,
  worldContext,
  difficultyPreference: difficultyPreference || 'adaptive',
  questParameters,
  timestamp: new Date().toISOString(),
  metadata: {
    processedBy: 'advanced-quest-generation',
    version: '2.0',
    requestId: `quest_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`
  }
};

return { json: questContext };

// Get campaign and world context for quest generation
const questContext = $input.first().json;
const { campaignId, worldContext, partyData } = questContext;

// Fetch campaign data from world state system
let campaignWorldState = null;
try {
  const worldResponse = await fetch('http://localhost:5678/webhook/world/update', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      action: 'get',
      campaignId
    })
  });

  if (worldResponse.ok) {
    const worldResult = await worldResponse.json();
    campaignWorldState = worldResult.data;
  }
} catch (error) {
  console.error('Failed to fetch world state:', error);
}

// Get active quest data
let activeQuests = [];
if (campaignWorldState && campaignWorldState.quests) {
  activeQuests = campaignWorldState.quests.filter(quest => 
    ['available', 'active', 'in_progress'].includes(quest.status)
  );
}

// Analyze party composition and capabilities
const partyAnalysis = {
  level: partyData.averageLevel || 3,
  size: partyData.partySize || 4,
  composition: partyData.composition || {
    tank: 1,
    healer: 1,
    damage: 2,
    support: 0,
    utility: 0
  },
  skills: partyData.partySkills || [],
  equipment: partyData.equipmentLevel || 'basic',
  experience: partyData.experienceLevel || 'normal',
  previousQuests: partyData.completedQuests || [],
  currentLocation: partyData.currentLocation || 'town',
  reputation: partyData.factionReputation || {}
};

// Analyze world state for quest opportunities
const worldAnalysis = {
  availableLocations: campaignWorldState?.locations?.filter(loc => loc.discovered) || [],
  activeNPCs: campaignWorldState?.npcs?.filter(npc => npc.status === 'alive') || [],
  factionRelations: campaignWorldState?.factions?.map(fac => ({
    id: fac.id,
    name: fac.name,
    reputation: fac.reputation || 0,
    alignment: fac.alignment || 'neutral'
  })) || [],
  recentEvents: campaignWorldState?.worldEvents?.slice(-10) || [],
  completedQuests: campaignWorldState?.quests?.filter(q => q.status === 'completed') || [],
  worldProgress: campaignWorldState?.worldStats || {},
  currentInGameTime: campaignWorldState?.currentInGameTime || 'Day 1, Morning'
};

// Calculate difficulty based on party and context
const calculateDifficulty = () => {
  const baseDifficulty = partyAnalysis.level;
  const partySizeModifier = partyAnalysis.size > 3 ? 0.2 : -0.1;
  const equipmentModifier = partyAnalysis.equipment === 'advanced' ? -0.2 : 
                          partyAnalysis.equipment === 'basic' ? 0.2 : 0;
  const experienceModifier = partyAnalysis.experience === 'veteran' ? -0.3 :
                           partyAnalysis.experience === 'new' ? 0.3 : 0;

  return Math.max(1, Math.min(20, Math.round(
    baseDifficulty + partySizeModifier + equipmentModifier + experienceModifier
  )));
};

const contextualData = {
  campaignId,
  campaignWorldState,
  partyAnalysis,
  worldAnalysis,
  activeQuests,
  calculatedDifficulty: calculateDifficulty(),
  currentContext: {
    location: partyAnalysis.currentLocation,
    timeOfDay: worldAnalysis.currentInGameTime,
    season: extractSeason(worldAnalysis.currentInGameTime),
    recentMajorEvents: worldAnalysis.recentEvents.filter(e => e.importance === 'major')
  },
  questOpportunities: identifyQuestOpportunities(),
  timestamp: new Date().toISOString()
};

// Helper functions
function extractSeason(timeString) {
  if (timeString.toLowerCase().includes('spring')) return 'spring';
  if (timeString.toLowerCase().includes('summer')) return 'summer';
  if (timeString.toLowerCase().includes('fall') || timeString.toLowerCase().includes('autumn')) return 'fall';
  if (timeString.toLowerCase().includes('winter')) return 'winter';
  return 'spring'; // default
}

function identifyQuestOpportunities() {
  const opportunities = [];

  // Location-based opportunities
  worldAnalysis.availableLocations.forEach(location => {
    if (location.properties?.dungeon || location.type === 'dungeon') {
      opportunities.push({
        type: 'dungeon_explore',
        location: location.id,
        priority: location.properties?.danger_level || 'normal'
      });
    }
    if (location.properties?.quests_available) {
      opportunities.push({
        type: 'location_quest',
        location: location.id,
        availableQuests: location.properties.quests_available
      });
    }
  });

  // NPC-based opportunities
  worldAnalysis.activeNPCs.forEach(npc => {
    if (npc.dialogue?.length > 0 && npc.faction !== 'neutral') {
      opportunities.push({
        type: 'npc_quest',
        npc: npc.id,
        faction: npc.faction,
        urgency: npc.properties?.quest_urgency || 'normal'
      });
    }
  });

  // Faction-based opportunities
  worldAnalysis.factionRelations.forEach(faction => {
    if (faction.reputation > 50) {
      opportunities.push({
        type: 'faction_favor',
        faction: faction.id,
        priority: 'high'
      });
    } else if (faction.reputation < -30) {
      opportunities.push({
        type: 'faction_repair',
        faction: faction.id,
        priority: 'medium'
      });
    }
  });

  // Recent events opportunities
  worldAnalysis.recentEvents.forEach(event => {
    if (event.type === 'disaster' || event.type === 'invasion') {
      opportunities.push({
        type: 'emergency_response',
        event: event.id,
        urgency: 'urgent'
      });
    }
  });

  return opportunities;
}

return { 
  json: {
    ...questContext,
    contextualData
  } 
};

// Procedural quest generation based on context and templates
const questContext = $input.first().json;
const { contextualData, questType, questParameters } = questContext;
const { partyAnalysis, worldAnalysis, questOpportunities, calculatedDifficulty } = contextualData;

// Quest templates and generation rules
const questTemplates = {
  // Combat-focused quests
  combat: {
    monster_hunt: {
      name: 'Monster Hunt: {target_type}',
      description: 'A dangerous {target_type} has been terrorizing {location}. Local authorities are offering a reward for its elimination.',
      objectives: [
        { type: 'travel', description: 'Travel to {location}' },
        { type: 'combat', description: 'Defeat the {target_type}' },
        { type: 'return', description: 'Report back to {giver}' }
      ],
      rewards: { experience: '{difficulty}00', gold: '{difficulty}00' },
      tags: ['combat', 'monster', 'reward']
    },
    bandit_trouble: {
      name: 'Bandit Problems',
      description: 'Bandits have been attacking travelers on the {road_name} road. The merchants need protection.',
      objectives: [
        { type: 'investigate', description: 'Investigate the bandit activity' },
        { type: 'combat', description: 'Deal with the bandits' },
        { type: 'escort', description: 'Escort merchant caravan' }
      ],
      rewards: { experience: '{difficulty}50', gold: '{difficulty}50', reputation: '{faction_name} +10' },
      tags: ['combat', 'bandits', 'escort']
    },
    arena_challenge: {
      name: 'Arena Championship',
      description: 'The local arena is holding a championship tournament. Glory and riches await the victors.',
      objectives: [
        { type: 'combat', description: 'Win {rounds} arena matches' },
        { type: 'combat', description: 'Defeat the champion' }
      ],
      rewards: { experience: '{difficulty}00', gold: '{difficulty}00', title: 'Arena Champion' },
      tags: ['combat', 'arena', 'glory']
    }
  },

  // Exploration quests
  exploration: {
    ancient_ruins: {
      name: 'Explore the {ruin_type} Ruins',
      description: 'Ancient {ruin_type} ruins have been discovered near {location}. Scholars believe they hold valuable artifacts and knowledge.',
      objectives: [
        { type: 'travel', description: 'Reach the ruins' },
        { type: 'explore', description: 'Explore the ruins completely' },
        { type: 'puzzle', description: 'Solve the ancient puzzles' },
        { type: 'recover', description: 'Recover the artifact' }
      ],
      rewards: { experience: '{difficulty}00', item: 'ancient_artifact', knowledge: true },
      tags: ['exploration', 'puzzle', 'ancient']
    },
    lost_expedition: {
      name: 'Find Lost Expedition',
      description: 'An expedition to {dangerous_location} has gone missing. Their families are desperate for news.',
      objectives: [
        { type: 'investigate', description: 'Find clues about the expedition\'s fate' },
        { type: 'travel', description: 'Reach {dangerous_location}' },
        { type: 'rescue', description: 'Rescue survivors or recover remains' }
      ],
      rewards: { experience: '{difficulty}00', gold: '{difficulty}00', gratitude: 'expedition_families' },
      tags: ['exploration', 'rescue', 'mystery']
    },
    map_cartography: {
      name: 'Chart the {region_name}',
      description: 'The cartographer\'s guild needs accurate maps of the unexplored {region_name} region.',
      objectives: [
        { type: 'explore', description: 'Survey {location_count} key locations' },
        { type: 'document', description: 'Create detailed maps' },
        { type: 'return', description: 'Deliver maps to the guild' }
      ],
      rewards: { experience: '{difficulty}00', gold: '{difficulty}00', reputation: 'Cartographer\'s Guild +20' },
      tags: ['exploration', 'mapping', 'survey']
    }
  },

  // Social and intrigue quests
  social: {
    political_intrigue: {
      name: 'Political Intrigue',
      description: 'A political crisis is brewing in {city_name}. {noble_name} needs your help to navigate the dangerous waters of court politics.',
      objectives: [
        { type: 'investigate', description: 'Gather information about rival factions' },
        { type: 'social', description: 'Build alliances' },
        { type: 'diplomacy', description: 'Resolve the political conflict' }
      ],
      rewards: { experience: '{difficulty}00', gold: '{difficulty}00', influence: 'political_favor' },
      tags: ['social', 'politics', 'intrigue']
    },
    missing_person: {
      name: 'Missing Person: {person_name}',
      description: '{person_name} has gone missing under mysterious circumstances. Their family is offering a substantial reward for their safe return.',
      objectives: [
        { type: 'investigate', description: 'Gather clues about the disappearance' },
        { type: 'social', description: 'Interview witnesses' },
        { type: 'rescue', description: 'Locate and rescue {person_name}' }
      ],
      rewards: { experience: '{difficulty}00', gold: '{difficulty}00', gratitude: 'family_favor' },
      tags: ['social', 'mystery', 'rescue']
    },
    festival_preparations: {
      name: 'Festival Preparations',
      description: 'The annual {festival_name} festival is approaching, but there are problems with the preparations.',
      objectives: [
        { type: 'social', description: 'Help with festival preparations' },
        { type: 'problem_solving', description: 'Resolve preparation issues' },
        { type: 'social', description: 'Ensure the festival runs smoothly' }
      ],
      rewards: { experience: '{difficulty}00', reputation: 'town_favor', celebration: true },
      tags: ['social', 'festival', 'community']
    }
  },

  // Delivery and escort quests
  delivery: {
    urgent_package: {
      name: 'Urgent Delivery',
      description: 'A urgent package must be delivered to {recipient} in {destination_city} as quickly as possible.',
      objectives: [
        { type: 'travel', description: 'Travel to {destination_city}' },
        { type: 'deliver', description: 'Deliver the package safely' },
        { type: 'return', description: 'Return with confirmation' }
      ],
      rewards: { experience: '{difficulty}00', gold: '{difficulty}00', reputation: 'merchant_guild +10' },
      tags: ['delivery', 'urgent', 'travel']
    },
    merchant_caravan: {
      name: 'Protect Merchant Caravan',
      description: 'A merchant caravan needs protection while traveling through {dangerous_route} to {destination}.',
      objectives: [
        { type: 'escort', description: 'Escort the merchant caravan' },
        { type: 'combat', description: 'Protect from bandits/monsters' },
        { type: 'deliver', description: 'Ensure safe arrival at destination' }
      ],
      rewards: { experience: '{difficulty}00', gold: '{difficulty}00', reputation: 'merchant_guild +15' },
      tags: ['escort', 'merchant', 'protection']
    }
  },

  // Collection and crafting quests
  collection: {
    rare_ingredients: {
      name: 'Collect Rare Ingredients',
      description: '{alchemist_name} needs rare ingredients from {dangerous_location} for an important potion.',
      objectives: [
        { type: 'collect', description: 'Gather {ingredient_count} {ingredient_name}' },
        { type: 'travel', description: 'Travel to {dangerous_location}' },
        { type: 'return', description: 'Deliver ingredients to {alchemist_name}' }
      ],
      rewards: { experience: '{difficulty}00', gold: '{difficulty}00', item: 'custom_potion' },
      tags: ['collection', 'ingredients', 'crafting']
    },
    ancient_artifacts: {
      name: 'Ancient Artifact Recovery',
      description: 'The museum is seeking ancient artifacts from the {ancient_civilization} civilization.',
      objectives: [
        { type: 'research', description: 'Research artifact locations' },
        { type: 'recover', description: 'Recover {artifact_count} artifacts' },
        { type: 'deliver', description: 'Deliver to the museum' }
      ],
      rewards: { experience: '{difficulty}00', gold: '{difficulty}00', reputation: 'museum +20' },
      tags: ['collection', 'artifacts', 'history']
    }
  }
};

// Quest generation based on opportunities and context
const generateQuest = () => {
  // Select appropriate quest category based on party and context
  let questCategory = selectQuestCategory();
  let questTemplate = selectQuestTemplate(questCategory);

  // Generate quest specifics
  const questSpecifics = generateQuestSpecifics(questTemplate);

  // Build complete quest object
  const quest = {
    id: `quest_${Date.now()}_${Math.random().toString(36).substr(2, 8)}`,
    name: fillTemplate(questTemplate.name, questSpecifics),
    description: fillTemplate(questTemplate.description, questSpecifics),
    type: questType,
    category: questCategory,
    difficulty: calculatedDifficulty,
    recommendedLevel: partyAnalysis.level,
    estimatedDuration: estimateQuestDuration(questTemplate),

    // Quest objectives
    objectives: questTemplate.objectives.map(obj => ({
      ...obj,
      id: `obj_${Date.now()}_${Math.random().toString(36).substr(2, 4)}`,
      description: fillTemplate(obj.description, questSpecifics),
      completed: false,
      completedAt: null
    })),

    // Quest giver and location
    giver: questSpecifics.giver,
    giverLocation: questSpecifics.giverLocation,
    questLocation: questSpecifics.questLocation,

    // Rewards
    rewards: processRewards(questTemplate.rewards, questSpecifics),

    // Quest metadata
    prerequisites: generatePrerequisites(questTemplate, questSpecifics),
    failureConditions: generateFailureConditions(questTemplate, questSpecifics),
    timeLimit: questSpecifics.timeLimit || null,

    // Quest state
    status: 'available',
    progress: 0,
    startedAt: null,
    completedAt: null,

    // Quest tags and metadata
    tags: questTemplate.tags,
    importance: calculateQuestImportance(questTemplate, questSpecifics),
    urgency: questSpecifics.urgency || 'normal',

    // Quest branching
    branches: generatePotentialBranches(questTemplate, questSpecifics),
    consequences: generateConsequences(questTemplate, questSpecifics),

    // Creation metadata
    createdAt: new Date().toISOString(),
    generatedBy: 'procedural_generator',
    generationContext: {
      partyLevel: partyAnalysis.level,
      partySize: partyAnalysis.size,
      worldEvents: worldAnalysis.recentEvents.slice(-3),
      triggeredBy: questOpportunities[0]?.type || 'contextual'
    }
  };

  return quest;
};

// Helper functions for quest generation
function selectQuestCategory() {
  const categories = Object.keys(questTemplates);

  // Weight categories based on party composition
  const weights = {
    combat: partyAnalysis.combat > 0.7 ? 3 : 1,
    exploration: partyAnalysis.exploration > 0.5 ? 2 : 1,
    social: partyAnalysis.social > 0.6 ? 2 : 1,
    delivery: partyAnalysis.size <= 2 ? 2 : 1,
    collection: partyAnalysis.crafting > 0.4 ? 2 : 1
  };

  // Select weighted random category
  const weightedCategories = [];
  categories.forEach(cat => {
    for (let i = 0; i < (weights[cat] || 1); i++) {
      weightedCategories.push(cat);
    }
  });

  return weightedCategories[Math.floor(Math.random() * weightedCategories.length)];
}

function selectQuestTemplate(category) {
  const templates = questTemplates[category];
  const templateNames = Object.keys(templates);
  const selectedName = templateNames[Math.floor(Math.random() * templateNames.length)];
  return templates[selectedName];
}

function generateQuestSpecifics(template) {
  const specifics = {};

  // Generate location-specific data
  if (worldAnalysis.availableLocations.length > 0) {
    const location = worldAnalysis.availableLocations[Math.floor(Math.random() * worldAnalysis.availableLocations.length)];
    specifics.questLocation = location.name;
    specifics.locationId = location.id;
    specifics.locationType = location.type;
  }

  // Generate NPC-specific data
  if (worldAnalysis.activeNPCs.length > 0) {
    const npc = worldAnalysis.activeNPCs[Math.floor(Math.random() * worldAnalysis.activeNPCs.length)];
    specifics.giver = npc.name;
    specifics.giverId = npc.id;
    specifics.giverLocation = npc.location;
    specifics.giverFaction = npc.faction;
  }

  // Generate faction-specific data
  if (worldAnalysis.factionRelations.length > 0) {
    const faction = worldAnalysis.factionRelations[Math.floor(Math.random() * worldAnalysis.factionRelations.length)];
    specifics.factionName = faction.name;
    specifics.factionId = faction.id;
    specifics.factionReputation = faction.reputation;
  }

  // Generate template-specific details
  specifics.difficulty = calculatedDifficulty;
  specifics.target_type = generateTargetType();
  specifics.ruin_type = generateRuinType();
  specifics.dangerous_location = generateDangerousLocation();
  specifics.ingredient_name = generateIngredientName();
  specifics.artifact_name = generateArtifactName();

  return specifics;
}

function generateTargetType() {
  const types = ['goblin', 'orc', 'dragon', 'undead', 'beast', 'elemental', 'demon', 'giant'];
  return types[Math.floor(Math.random() * types.length)];
}

function generateRuinType() {
  const types = ['elven', 'dwarven', 'ancient', 'magical', 'cursed', 'forgotten', 'sacred'];
  return types[Math.floor(Math.random() * types.length)];
}

function generateDangerousLocation() {
  const locations = ['dark forest', 'swamp', 'mountains', 'dungeon', 'cave system', 'ruined castle', 'abandoned mine'];
  return locations[Math.floor(Math.random() * locations.length)];
}

function generateIngredientName() {
  const ingredients = ['moonpetal', 'dragon scale', 'phoenix feather', 'unicorn horn', 'crystal shard', 'rare herb'];
  return ingredients[Math.floor(Math.random() * ingredients.length)];
}

function generateArtifactName() {
  const artifacts = ['ancient sword', 'magical amulet', 'sacred relic', 'crown of power', 'staff of wisdom'];
  return artifacts[Math.floor(Math.random() * artifacts.length)];
}

function fillTemplate(template, specifics) {
  let result = template;
  Object.keys(specifics).forEach(key => {
    const placeholder = `{${key}}`;
    result = result.replace(new RegExp(placeholder, 'g'), specifics[key]);
  });

  // Replace difficulty placeholders
  result = result.replace(/{difficulty}/g, calculatedDifficulty);

  return result;
}

function estimateQuestDuration(template) {
  const baseDuration = {
    combat: '2-4 hours',
    exploration: '4-6 hours',
    social: '2-3 hours',
    delivery: '1-2 hours',
    collection: '3-5 hours'
  };

  const category = Object.keys(questTemplates).find(cat => 
    Object.values(questTemplates[cat]).includes(template)
  );

  return baseDuration[category] || '3-4 hours';
}

function processRewards(templateRewards, specifics) {
  const rewards = { ...templateRewards };

  // Process numeric rewards based on difficulty
  if (rewards.experience && typeof rewards.experience === 'string') {
    rewards.experience = parseInt(rewards.experience.replace('{difficulty}', calculatedDifficulty));
  }

  if (rewards.gold && typeof rewards.gold === 'string') {
    rewards.gold = parseInt(rewards.gold.replace('{difficulty}', calculatedDifficulty)) * 10;
  }

  return rewards;
}

function generatePrerequisites(template, specifics) {
  const prerequisites = [];

  // Level prerequisite
  prerequisites.push({
    type: 'level',
    value: Math.max(1, calculatedDifficulty - 2),
    description: `Minimum level ${Math.max(1, calculatedDifficulty - 2)}`
  });

  // Context-based prerequisites
  if (specifics.factionReputation && specifics.factionReputation < -20) {
    prerequisites.push({
      type: 'reputation',
      faction: specifics.factionId,
      value: -20,
      description: `Better reputation with ${specifics.factionName} required`
    });
  }

  return prerequisites;
}

function generateFailureConditions(template, specifics) {
  return [
    {
      type: 'time_limit',
      description: 'Quest time limit exceeded',
      enabled: !!specifics.timeLimit
    },
    {
      type: 'death',
      description: 'Party members die',
      enabled: true
    },
    {
      type: 'abandonment',
      description: 'Quest is abandoned',
      enabled: true
    }
  ].filter(condition => condition.enabled);
}

function calculateQuestImportance(template, specifics) {
  let importance = 5; // base importance

  // Adjust based on urgency
  if (specifics.urgency === 'urgent') importance += 2;
  if (specifics.urgency === 'critical') importance += 4;

  // Adjust based on rewards
  if (template.rewards.item) importance += 1;
  if (template.rewards.title) importance += 2;

  // Adjust based on faction alignment
  if (specifics.factionReputation > 50) importance += 1;
  if (specifics.factionReputation < -30) importance += 1;

  return Math.min(10, importance);
}

function generatePotentialBranches(template, specifics) {
  const branches = [];

  // Generate moral choice branches
  if (template.tags.includes('combat')) {
    branches.push({
      id: 'spare_enemies',
      name: 'Spare the enemies',
      description: 'Show mercy to defeated foes',
      consequences: { reputation: 'mercy', rewards: { gold: -50 } }
    });
  }

  if (template.tags.includes('social')) {
    branches.push({
      id: 'diplomatic_solution',
      name: 'Seek diplomatic solution',
      description: 'Resolve conflict through diplomacy rather than force',
      consequences: { reputation: 'peace', rewards: { experience: '+20%' } }
    });
  }

  return branches;
}

function generateConsequences(template, specifics) {
  return {
    completion: {
      worldChanges: [
        `${specifics.questLocation} becomes safer`,
        `Relationship with ${specifics.factionName || 'locals'} improves`
      ],
      factionChanges: specifics.factionId ? {
        [specifics.factionId]: '+10'
      } : {},
      storyProgress: 'Main story advances'
    },
    failure: {
      worldChanges: [
        `${specifics.questLocation} becomes more dangerous`,
        `Relationship with ${specifics.factionName || 'locals'} deteriorates`
      ],
      factionChanges: specifics.factionId ? {
        [specifics.factionId]: '-5'
      } : {}
    }
  };
}

// Generate the quest
const generatedQuest = generateQuest();

return { json: { quest: generatedQuest, generationMethod: 'procedural', contextualData } };

parameters.prompt:
Generate a detailed D&D quest based on the following context and requirements:

Context:
Campaign: {{ $json.contextualData.campaignId }}
Party Level: {{ $json.contextualData.partyAnalysis.level }}
Party Size: {{ $json.contextualData.partyAnalysis.size }}
Current Location: {{ $json.contextualData.partyAnalysis.currentLocation }}
Quest Type: {{ $json.questType }}
Difficulty: {{ $json.difficultyPreference }}

Available Locations: {{ $json.contextualData.worldAnalysis.availableLocations.map(l => l.name).join(', ') }}
Active NPCs: {{ $json.contextualData.worldAnalysis.activeNPCs.map(n => n.name).join(', ') }}
Recent Events: {{ $json.contextualData.worldAnalysis.recentEvents.slice(-3).map(e => e.description).join('; ') }}

Quest Opportunities: {{ $json.contextualData.questOpportunities.map(o => o.type + ' at ' + (o.location || o.npc || o.faction)).join(', ') }}

Generate a quest that:
1. Is appropriate for the party level and composition
2. Fits the current world context and recent events
3. Includes 3-5 clear objectives
4. Has meaningful rewards and consequences
5. Offers interesting choices and potential branches
6. Connects to the existing world and NPCs

Please respond with a JSON object containing the quest details in this format:
{
  "name": "Quest Name",
  "description": "Detailed description",
