// Quest branching and consequence tracking system
const questData = $input.first().json;
const { quest, contextualData } = questData;

// Create enhanced quest with branching logic and consequence tracking
const enhancedQuest = {
  ...quest,

  // Quest state management
  state: {
    currentPhase: 'available', // available, active, paused, completed, failed, abandoned
    currentObjective: 0,
    completedObjectives: [],
    failedObjectives: [],
    activeBranches: [],
    takenChoices: [],

    // Progress tracking
    progress: {
      overall: 0.0, // 0.0-1.0
      objectives: quest.objectives.map(obj => ({
        id: obj.id,
        progress: 0.0,
        completed: false,
        failed: false,
        notes: []
      })),
      timeSpent: 0, // in minutes
      attempts: 0
    },

    // Dynamic difficulty adjustment
    difficultyAdjustment: {
      currentDifficulty: quest.difficulty,
      adjustmentHistory: [],
      recommendedChanges: []
    }
  },

  // Advanced branching system
  branching: {
    conditionalBranches: generateConditionalBranches(quest, contextualData),
    randomEvents: generateRandomEvents(quest, contextualData),
    environmentalFactors: generateEnvironmentalFactors(quest, contextualData),
    playerChoiceImpact: generatePlayerChoiceImpact(quest, contextualData)
  },

  // Consequence tracking
  consequences: {
    immediate: generateImmediateConsequences(quest),
    shortTerm: generateShortTermConsequences(quest, contextualData),
    longTerm: generateLongTermConsequences(quest, contextualData),
    worldImpact: generateWorldImpact(quest, contextualData),

    // Consequence tracking
    tracking: {
      triggeredConsequences: [],
      avoidedConsequences: [],
      modifiedConsequences: [],
      unexpectedConsequences: []
    }
  },

  // Quest discovery mechanics
  discovery: {
    discoveryMethod: contextualData.questOpportunities[0]?.type || 'contextual',
    discoveredBy: [], // party members who discovered this quest
    hiddenObjectives: generateHiddenObjectives(quest, contextualData),
    secretRewards: generateSecretRewards(quest, contextualData),

    // Discovery requirements
    requirements: {
      skills: [],
      items: [],
      knowledge: [],
      reputation: {}
    }
  },

  // Quest relationships and dependencies
  relationships: {
    prerequisites: generateQuestPrerequisites(quest, contextualData),
    blocks: [], // quests this quest blocks
    unlocks: [], // quests this quest unlocks
    conflicts: [], // quests that conflict with this one

    // Relationship tracking
    questLines: determineQuestLines(quest, contextualData),
    relatedNPCs: identifyRelatedNPCs(quest, contextualData),
    relatedLocations: identifyRelatedLocations(quest, contextualData)
  },

  // Scaling and adaptation
  scaling: {
    partySizeScaling: generatePartySizeScaling(quest),
    levelScaling: generateLevelScaling(quest, contextualData),
    difficultyScaling: generateDifficultyScaling(quest, contextualData),
    contentScaling: generateContentScaling(quest, contextualData)
  },

  // Quest metadata and analytics
  analytics: {
    estimatedPlayTime: calculateEstimatedPlayTime(quest),
    combatVsRoleplayRatio: calculateCombatRoleplayRatio(quest),
    riskAssessment: calculateRiskAssessment(quest, contextualData),
    rewardEfficiency: calculateRewardEfficiency(quest),

    // Player engagement metrics
    engagementFactors: calculateEngagementFactors(quest, contextualData),
    replayability: calculateReplayabilityScore(quest),
    uniqueness: calculateUniquenessScore(quest, contextualData)
  }
};

// Helper functions for advanced quest features
function generateConditionalBranches(quest, context) {
  const branches = [];

  // Generate branches based on quest type
  if (quest.tags.includes('combat')) {
    branches.push({
      id: 'combat_outcome',
      type: 'conditional',
      trigger: 'combat_result',
      conditions: [
        {
          condition: 'decisive_victory',
          branch: {
            name: 'Crushing Victory',
            description: 'The enemies were defeated with overwhelming force',
            consequences: {
              reputation: 'fear',
              rewards: { experience: '+20%' },
              newObjectives: ['Investigate rumors of your strength']
            }
          }
        },
        {
          condition: 'costly_victory',
          branch: {
            name: 'Hard-Won Victory',
            description: 'Victory came at a great cost',
            consequences: {
              reputation: 'respect',
              rewards: { experience: '+10%' },
              newObjectives: ['Recover and tend to the wounded']
            }
          }
        }
      ]
    });
  }

  if (quest.tags.includes('social')) {
    branches.push({
      id: 'social_approach',
      type: 'conditional',
      trigger: 'social_interaction',
      conditions: [
        {
          condition: 'diplomatic_success',
          branch: {
            name: 'Peaceful Resolution',
            description: 'The conflict was resolved through diplomacy',
            consequences: {
              reputation: 'peacekeeper',
              rewards: { experience: '+15%' },
              newAlliances: ['conflicting_faction']
            }
          }
        },
        {
          condition: 'intimidation_success',
          branch: {
            name: 'Forced Compliance',
            description: 'The conflict was resolved through threats',
            consequences: {
              reputation: 'intimidator',
              rewards: { gold: '+20%' },
              resentment: ['target_faction']
            }
          }
        }
      ]
    });
  }

  return branches;
}

function generateRandomEvents(quest, context) {
  const events = [];

  // Environmental events
  if (quest.tags.includes('exploration')) {
    events.push({
      id: 'weather_change',
      type: 'environmental',
      probability: 0.3,
      description: 'Sudden storm complicates travel',
      effects: {
        movement_speed: '-50%',
        visibility: 'poor',
        new_challenge: 'navigation'
      }
    });
  }

  // Combat events
  if (quest.tags.includes('combat')) {
    events.push({
      id: 'reinforcements',
      type: 'combat',
      probability: 0.2,
      description: 'Enemy reinforcements arrive',
      effects: {
        enemy_count: '+50%',
        difficulty: '+1',
        time_limit: 'reduced'
      }
    });
  }

  return events;
}

function generateEnvironmentalFactors(quest, context) {
  const factors = [];

  // Time of day effects
  factors.push({
    type: 'time_of_day',
    day_effects: {
      visibility: 'normal',
      npc_activity: 'high',
      combat_advantage: 'neutral'
    },
    night_effects: {
      visibility: 'poor',
      npc_activity: 'low',
      combat_advantage: 'stealth'
    }
  });

  // Weather effects
  factors.push({
    type: 'weather',
    clear_effects: {
      travel_speed: 'normal',
      morale: 'normal',
      visibility: 'excellent'
    },
    rain_effects: {
      travel_speed: '-25%',
      morale: 'reduced',
      visibility: 'poor'
    }
  });

  return factors;
}

function generatePlayerChoiceImpact(quest, context) {
  return {
    moralChoices: [
      {
        choice: 'spare vs kill',
        impact: {
          spare: {
            reputation: 'mercy',
            future_encounters: 'allies_possible',
            rewards: {experience: '-20%', gratitude: 'potential_ally'}
          },
          kill: {
            reputation: 'ruthless',
            future_encounters: 'no_allies',
            rewards: {experience: '+20%', gratitude: 'fear'}
          }
        }
      }
    ],
    strategicChoices: [
      {
        choice: 'stealth vs direct',
        impact: {
          stealth: {
            risk: 'low',
            rewards: {experience: '+10%', surprise: 'advantage'},
            detection_consequences: 'alarm_raised'
          },
          direct: {
            risk: 'high',
            rewards: {experience: '+25%', glory: 'courageous'},
            consequences: 'preparation_lost'
          }
        }
      }
    ]
  };
}

function generateImmediateConsequences(quest) {
  return {
    success: [
      'Quest giver rewards party',
      'Local reputation improves',
      'Experience gained'
    ],
    failure: [
      'Quest giver disappointed',
      'Local reputation suffers',
      'Potential penalties'
    ]
  };
}

function generateShortTermConsequences(quest, context) {
  return {
    success: [
      'New opportunities become available',
      'Related factions notice your success',
      'World changes in quest location'
    ],
    failure: [
      'Related quests become unavailable',
      'Faction relationships deteriorate',
      'World situation worsens'
    ]
  };
}

function generateLongTermConsequences(quest, context) {
  return {
    success: [
      'Party becomes known for this type of work',
      'Major storylines may be affected',
      'World history records your actions'
    ],
    failure: [
      'Party develops negative reputation',
      'Major storylines may be blocked',
      'World remembers your failure'
    ]
  };
}

function generateWorldImpact(quest, context) {
  return {
    location_changes: {
      [quest.questLocation]: {
        safety: quest.tags.includes('combat') ? 'improved' : 'unchanged',
        economy: quest.tags.includes('delivery') ? 'improved' : 'unchanged',
        knowledge: quest.tags.includes('exploration') ? 'improved' : 'unchanged'
      }
    },
    faction_changes: {
      [quest.giverFaction]: {
        relationship: '+15',
        influence: '+5',
        power: 'unchanged'
      }
    },
    global_changes: []
  };
}

function generateHiddenObjectives(quest, context) {
  const hidden = [];

  if (quest.tags.includes('exploration')) {
    hidden.push({
      id: 'hidden_treasure',
      description: 'Find the hidden treasure chamber',
      requirement: 'perception_check DC 20',
      reward: { gold: 'double', item: 'magical_item' },
      discovered: false
    });
  }

  return hidden;
}

function generateSecretRewards(quest, context) {
  return [
    {
      type: 'hidden_achievement',
      name: 'Secret Success',
      description: 'Completed quest with optimal outcome',
      requirement: 'all_objectives_perfect',
      reward: { title: 'Master Adventurer', reputation: 'all_factions +10' }
    }
  ];
}

function calculateEstimatedPlayTime(quest) {
  const baseTime = {
    combat: 60, // minutes per combat encounter
    exploration: 45, // minutes per exploration area
    social: 30, // minutes per social encounter
    travel: 15, // minutes per travel segment
    puzzle: 40 // minutes per puzzle
  };

  let totalTime = 0;
  quest.objectives.forEach(obj => {
    const type = obj.type;
    totalTime += baseTime[type] || 30;
  });

  return totalTime;
}

function calculateCombatRoleplayRatio(quest) {
  const combatObjectives = quest.objectives.filter(obj => 
    ['combat', 'escort', 'protect'].includes(obj.type)
  ).length;

  const roleplayObjectives = quest.objectives.filter(obj => 
    ['social', 'diplomacy', 'investigate'].includes(obj.type)
  ).length;

  const total = quest.objectives.length;

  return {
    combat: Math.round((combatObjectives / total) * 100),
    roleplay: Math.round((roleplayObjectives / total) * 100),
    mixed: Math.round(((total - combatObjectives - roleplayObjectives) / total) * 100)
  };
}

// Add all the helper functions
function generatePartySizeScaling(quest) {
  return {
    solo: {
      health_modifier: 0.5,
      damage_modifier: 0.7,
      reward_modifier: 1.5
    },
    duo: {
      health_modifier: 0.7,
      damage_modifier: 0.8,
      reward_modifier: 1.2
    },
    full_party: {
      health_modifier: 1.0,
      damage_modifier: 1.0,
      reward_modifier: 1.0
    },
    large_party: {
      health_modifier: 1.3,
      damage_modifier: 1.2,
      reward_modifier: 0.8
    }
  };
}

function generateLevelScaling(quest, context) {
  const baseLevel = context.partyAnalysis.level;
  return {
    current_level: baseLevel,
    scaling_range: {
      min: baseLevel - 3,
      max: baseLevel + 3
    },
    adjustments: {
      enemy_count: 'linear',
      enemy_difficulty: 'scaled',
      puzzle_complexity: 'moderate',
      reward_quality: 'level_appropriate'
    }
  };
}

function generateDifficultyScaling(quest, context) {
  return {
    adaptive: true,
    metrics: [
      'party_performance',
      'time_spent',
      'resource_usage',
      'success_rate'
    ],
    adjustment_triggers: {
      struggling: 'reduce_difficulty',
      dominating: 'increase_difficulty',
      balanced: 'maintain_difficulty'
    }
  };
}

function generateContentScaling(quest, context) {
  return {
    optional_content: generateOptionalContent(quest, context),
    bonus_objectives: generateBonusObjectives(quest, context),
    challenge_modes: generateChallengeModes(quest, context)
  };
}

function generateOptionalContent(quest, context) {
  return [
    {
      id: 'side_dungeon',
      name: 'Bonus Dungeon',
      description: 'Optional dungeon with extra rewards',
      difficulty: quest.difficulty + 1,
      estimated_time: 60,
      rewards: { experience: 500, gold: 1000 }
    }
  ];
}

function generateBonusObjectives(quest, context) {
  return [
    {
      id: 'speed_run',
      name: 'Speed Run',
      description: 'Complete quest within time limit',
      time_limit: '50% of estimated time',
      reward: { experience: '+25%', title: 'Swift Adventurer' }
    }
  ];
}

function generateChallengeModes(quest, context) {
  return [
    {
      id: 'hardcore',
      name: 'Hardcore Mode',
      description: 'Increased difficulty with better rewards',
      modifiers: {
        enemy_health: '+50%',
        enemy_damage: '+25%',
        death_penalty: 'permanent'
      },
      rewards: { experience: '+50%', gold: '+75%', unique_items: 1 }
    }
  ];
}

function calculateRiskAssessment(quest, context) {
  const riskFactors = {
    combat_risk: quest.tags.includes('combat') ? 0.7 : 0.3,
    death_risk: quest.difficulty > 10 ? 0.4 : 0.2,
    failure_risk: quest.objectives.length > 5 ? 0.3 : 0.2,
    resource_risk: quest.estimatedDuration > 180 ? 0.4 : 0.2
  };

  const totalRisk = Object.values(riskFactors).reduce((sum, risk) => sum + risk, 0) / Object.keys(riskFactors).length;

  return {
    overall_risk: Math.round(totalRisk * 100),
    risk_factors: riskFactors,
    mitigation_strategies: generateMitigationStrategies(riskFactors)
  };
}

function generateMitigationStrategies(riskFactors) {
  const strategies = [];

  if (riskFactors.combat_risk > 0.5) {
    strategies.push('Bring healing supplies and consider tactical retreat options');
  }

  if (riskFactors.death_risk > 0.3) {
    strategies.push('Ensure party has resurrection capabilities or backup plans');
  }

  return strategies;
}

function calculateRewardEfficiency(quest) {
  const estimatedTime = calculateEstimatedPlayTime(quest);
  const totalRewards = (quest.rewards.experience || 0) + ((quest.rewards.gold || 0) / 10);

  return {
    rewards_per_hour: Math.round(totalRewards / (estimatedTime / 60)),
    time_efficiency: estimatedTime < 120 ? 'high' : estimatedTime < 240 ? 'medium' : 'low',
    reward_quality: quest.rewards.item ? 'high' : quest.rewards.gold > 1000 ? 'medium' : 'low'
  };
}

function calculateEngagementFactors(quest, context) {
  return {
    variety: quest.objectives.length > 3 ? 'high' : 'medium',
    player_agency: quest.branches.length > 2 ? 'high' : 'medium',
    story_integration: quest.consequences.worldImpact.length > 0 ? 'high' : 'medium',
    challenge_appropriateness: Math.abs(quest.difficulty - context.partyAnalysis.level) <= 2 ? 'high' : 'medium'
  };
}

function calculateReplayabilityScore(quest) {
  let score = 5; // base score

  if (quest.branching.conditionalBranches.length > 2) score += 2;
  if (quest.branching.randomEvents.length > 1) score += 1;
  if (quest.scaling.challenge_modes.length > 0) score += 1;
  if (quest.discovery.hiddenObjectives.length > 0) score += 1;

  return Math.min(10, score);
}

function calculateUniquenessScore(quest, context) {
  // Check against existing quests
  const existingQuests = context.activeQuests || [];
  const similarQuests = existingQuests.filter(existingQuest => {
    const tagOverlap = quest.tags.filter(tag => existingQuest.tags?.includes(tag)).length;
    const typeMatch = quest.type === existingQuest.type;
    return tagOverlap > 1 || typeMatch;
  });

  const uniquenessScore = Math.max(1, 10 - (similarQuests.length * 2));

  return uniquenessScore;
}

function generateQuestPrerequisites(quest, context) {
  const prerequisites = [];

  // Level prerequisites
  prerequisites.push({
    type: 'level',
    value: Math.max(1, quest.difficulty - 2),
    description: `Minimum level ${Math.max(1, quest.difficulty - 2)}`
  });

  // Skill prerequisites based on quest type
  if (quest.tags.includes('social')) {
    prerequisites.push({
      type: 'skill',
      skill: 'persuasion',
      minimum: 3,
      description: 'Persuasion skill level 3 recommended'
    });
  }

  return prerequisites;
}

function determineQuestLines(quest, context) {
  return [
    {
      name: 'Main Story',
      importance: quest.type === 'main' ? 'primary' : 'secondary',
      position: quest.type === 'main' ? 1 : Math.floor(Math.random() * 5) + 2
    }
  ];
}

function identifyRelatedNPCs(quest, context) {
  const relatedNPCs = [quest.giver];

  // Add NPCs from world context that might be related
  if (context.worldAnalysis.activeNPCs) {
    const factionNPCs = context.worldAnalysis.activeNPCs.filter(npc => 
      npc.faction === quest.giverFaction
    );
    relatedNPCs.push(...factionNPCs.slice(0, 2).map(npc => npc.name));
  }

  return relatedNPCs;
}

function identifyRelatedLocations(quest, context) {
  const locations = [quest.questLocation];

  // Add nearby locations from world context
  if (context.worldAnalysis.availableLocations) {
    const nearbyLocations = context.worldAnalysis.availableLocations.filter(loc => 
      loc.id !== quest.questLocation && Math.random() > 0.5
    );
    locations.push(...nearbyLocations.slice(0, 2).map(loc => loc.name));
  }

  return locations;
}

return { json: { enhancedQuest, originalQuest: quest, contextualData } };

// Update world state with new quest
const questData = $input.first().json;
const { enhancedQuest, contextualData } = questData;
const { campaignId } = contextualData;

// Prepare world state update
const worldUpdate = {
  action: 'update',
  campaignId,
  questChanges: [
    {
      questId: enhancedQuest.id,
      action: 'add',
      data: {
        id: enhancedQuest.id,
        name: enhancedQuest.name,
        description: enhancedQuest.description,
        type: enhancedQuest.type,
        status: enhancedQuest.status,
        difficulty: enhancedQuest.difficulty,
        objectives: enhancedQuest.objectives,
        rewards: enhancedQuest.rewards,
        giver: enhancedQuest.giver,
        location: enhancedQuest.questLocation,
        tags: enhancedQuest.tags,
        importance: enhancedQuest.importance,
        urgency: enhancedQuest.urgency,
        prerequisites: enhancedQuest.prerequisites,
        consequences: enhancedQuest.consequences,
        branching: enhancedQuest.branching,
        createdAt: enhancedQuest.createdAt,
        generatedBy: enhancedQuest.generatedBy
      }
    }
  ],
  worldEvents: [
    {
      id: `event_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`,
      type: 'quest_generated',
      description: `New quest "${enhancedQuest.name}" became available`,
      location: enhancedQuest.questLocation,
      importance: enhancedQuest.importance > 7 ? 'major' : 'minor',
      relatedNPCs: [enhancedQuest.giver],
      relatedQuests: [enhancedQuest.id],
      timestamp: new Date().toISOString()
    }
  ],
  metadata: {
    questGeneration: {
      questId: enhancedQuest.id,
      generationMethod: enhancedQuest.generatedBy,
      questType: enhancedQuest.type,
      difficulty: enhancedQuest.difficulty,
      partyLevel: contextualData.partyAnalysis.level
    }
  }
};

// Update world state
let worldUpdateResult = null;
try {
  const worldResponse = await fetch('http://localhost:5678/webhook/world/update', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(worldUpdate)
  });

  if (worldResponse.ok) {
    worldUpdateResult = await worldResponse.json();
  }
} catch (error) {
  console.error('Failed to update world state:', error);
}

return { 
  json: {
    quest: enhancedQuest,
    worldUpdateResult,
    contextualData
  } 
};

// Send quest notifications to relevant systems
const questData = $input.first().json;
const { quest, contextualData } = questData;

// Prepare WebSocket broadcast payload
const broadcastPayload = {
  type: 'quest_generated',
  data: {
    questId: quest.id,
    questName: quest.name,
    questType: quest.type,
    difficulty: quest.difficulty,
    giver: quest.giver,
    location: quest.questLocation,
    importance: quest.importance,
    urgency: quest.urgency,
    estimatedDuration: quest.estimatedDuration,
    campaignId: contextualData.campaignId,
    tags: quest.tags
  },
  channels: [
    `campaign_${contextualData.campaignId}`,
    'quest_updates',
    'dm_updates'
  ],
  timestamp: new Date().toISOString()
};

// Send to WebSocket system
fetch('http://localhost:5678/webhook/websocket/broadcast', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json'
  },
  body: JSON.stringify(broadcastPayload)
}).catch(error => {
  console.error('Failed to broadcast quest generation:', error);
});

// Send notification to quest giver NPC system
if (quest.giver) {
  const npcNotificationPayload = {
    type: 'npc_quest_update',
    data: {
      npcId: quest.giver,
      questId: quest.id,
      action: 'quest_available',
      questDetails: {
        name: quest.name,
        type: quest.type,
        difficulty: quest.difficulty,
        urgency: quest.urgency
      }
    },
    channels: [`npc_${quest.giver}`, 'npc_updates'],
    timestamp: new Date().toISOString()
  };

  fetch('http://localhost:5678/webhook/websocket/broadcast', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(npcNotificationPayload)
  }).catch(error => {
    console.error('Failed to send NPC notification:', error);
  });
}

// Send location-specific notifications
if (quest.questLocation) {
  const locationNotificationPayload = {
    type: 'location_quest_update',
    data: {
      locationId: quest.questLocation,
      questId: quest.id,
      questName: quest.name,
      questType: quest.type,
      newActivity: true
    },
    channels: [`location_${quest.questLocation}`, 'location_updates'],
    timestamp: new Date().toISOString()
  };

  fetch('http://localhost:5678/webhook/websocket/broadcast', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(locationNotificationPayload)
  }).catch(error => {
    console.error('Failed to send location notification:', error);
  });
}

return { json: { broadcast: 'sent', questId: quest.id, notifications: ['general', 'npc', 'location'] } };
